#include <bits/stdc++.h>
#include <omp.h>
using namespace std;
static inline uint32_t pack4(uint8_t x,uint8_t y,uint8_t dx,uint8_t dy){return (uint32_t)x|((uint32_t)y<<8)|((uint32_t)dx<<16)|((uint32_t)dy<<24);}static inline void unpack4(uint32_t s,uint8_t &x,uint8_t &y,uint8_t &dx,uint8_t &dy){x=s&255;y=(s>>8)&255;dx=(s>>16)&255;dy=(s>>24)&255;}
struct FlatMap{static const uint32_t EMPTY=0xffffffffu;size_t cap,mask;vector<uint32_t> keys,vals;FlatMap(size_t p2):cap(1ull<<p2),mask(cap-1),keys(cap,EMPTY),vals(cap){}static inline uint64_t mix(uint64_t x){x+=0x9e3779b97f4a7c15ULL;x=(x^(x>>30))*0xbf58476d1ce4e5b9ULL;x=(x^(x>>27))*0x94d049bb133111ebULL;return x^(x>>31);}uint32_t* findv(uint32_t k){size_t i=mix(k)&mask;while(true){if(keys[i]==k)return &vals[i];if(keys[i]==EMPTY)return nullptr;i=(i+1)&mask;}}pair<uint32_t,bool> getinsert(uint32_t k,uint32_t v){size_t i=mix(k)&mask;while(true){if(keys[i]==k)return {vals[i],false};if(keys[i]==EMPTY){keys[i]=k;vals[i]=v;return {v,true};}i=(i+1)&mask;}}};
struct TC{int h;uint8_t mask;TC(int hh):h(hh),mask((1u<<hh)-1){}inline uint32_t reduce(uint32_t s)const{uint8_t x,y,dx,dy;unpack4(s,x,y,dx,dy);if(x&(1u<<(h-1))){x^=mask;y^=mask;}return pack4(x,y,dx,dy);}uint32_t trans(uint32_t s,int c,int l)const{uint8_t x,y,dx,dy;unpack4(s,x,y,dx,dy);int ta=l>=0?l+1:1,tb=l<0?-l+1:1,na=h+ta,nb=h+tb;int16_t L[17][17];L[h][h]=h;int cur=h;for(int k=h-1;k>=0;--k){cur-=(dx>>(h-1-k))&1;L[k][h]=cur;}cur=h;for(int k=h-1;k>=0;--k){cur-=(dy>>(h-1-k))&1;L[h][k]=cur;}auto achar=[&](int i){if(i<=h)return int((x>>(h-i))&1);int q=i-h-1;if(l>=0)return q<l?1-c:c;return c;};auto bchar=[&](int j){if(j<=h)return int((y>>(h-j))&1);int q=j-h-1;if(l<0)return q<(-l)?1-c:c;return c;};for(int i=0;i<=na;i++)for(int j=0;j<=nb;j++)if(i>h||j>h){if(i==0)L[i][j]=L[i][j-1];else if(j==0)L[i][j]=L[i-1][j];else if(achar(i)==bchar(j))L[i][j]=L[i-1][j-1]+1;else L[i][j]=max(L[i][j-1],L[i-1][j]);}int i=na,j=nb;while(i>=h&&j>=h){if(L[i][j]==L[i-1][j])--i;else if(L[i][j]==L[i][j-1])--j;else{--i;--j;}if(i==h&&j==h){uint8_t xs=x,ys=y;if(l>=0){for(int q=0;q<l;q++)xs=((xs<<1)|(1-c))&mask;xs=((xs<<1)|c)&mask;ys=((ys<<1)|c)&mask;}else{xs=((xs<<1)|c)&mask;for(int q=0;q<-l;q++)ys=((ys<<1)|(1-c))&mask;ys=((ys<<1)|c)&mask;}uint8_t ndx=0,ndy=0;for(int k=na-h+1;k<=na;k++)ndx=(ndx<<1)|(L[k][nb]-L[k-1][nb]);for(int k=nb-h+1;k<=nb;k++)ndy=(ndy<<1)|(L[na][k]-L[na][k-1]);return reduce(pack4(xs,ys,ndx,ndy));}}return UINT32_MAX;}};
int main(int argc,char**argv){if(argc<2)return 2;string out=argv[1];TC tc(8);uint32_t start=tc.reduce(pack4(0,0,255,255));FlatMap mp(24);vector<uint32_t> states;states.reserve(7000000);states.push_back(start);mp.getinsert(start,1);FILE*fp=fopen(out.c_str(),"wb");if(!fp){perror("fopen");return 3;}const size_t BS=4096;vector<uint32_t> raw(BS*30),idxs(BS*30);size_t head=0;auto T0=chrono::steady_clock::now();while(head<states.size()){size_t end=min(states.size(),head+BS), n=end-head;
#pragma omp parallel for schedule(static)
for(long long bi=0;bi<(long long)n;bi++){uint32_t s=states[head+bi];int j=0;for(int c=0;c<2;c++)for(int l=-7;l<=7;l++,j++)raw[bi*30+j]=tc.trans(s,c,l);}
for(size_t bi=0;bi<n;bi++)for(int j=0;j<30;j++){uint32_t t=raw[bi*30+j],ti=0;if(t!=UINT32_MAX){auto pr=mp.getinsert(t,(uint32_t)states.size()+1);ti=pr.first;if(pr.second)states.push_back(t);}idxs[bi*30+j]=ti;}fwrite(idxs.data(),4,n*30,fp);head=end;if(head%(BS*64)==0||head==states.size()){double sec=chrono::duration<double>(chrono::steady_clock::now()-T0).count();cerr<<"head="<<head<<" states="<<states.size()<<" sec="<<sec<<"\n";}}
fclose(fp);cerr<<"FINAL states="<<states.size()<<"\n";return states.size()==6419109?0:4;}
